class WebViewAssetLoader {
    private final String domain;
    private final java.util.Map<String, PathHandler> handlers = new java.util.HashMap<>();

    private WebViewAssetLoader(String domain, java.util.Map<String, PathHandler> handlers) {
        this.domain = domain;
        this.handlers.putAll(handlers);
    }

    public WebResourceResponse shouldInterceptRequest(Uri url) {
        // Very simple stub logic: if the url contains a registered path, return a dummy response.
        String u = url.toString();
        for (String path : handlers.keySet()) {
            if (u.contains(path)) {
                return new WebResourceResponse("text/html", "UTF-8", "<html><body>Loaded from assets: " + u + "</body></html>");
            }
        }
        return null;
    }

    public interface PathHandler {
    }

    public static class AssetsPathHandler implements PathHandler {
        private final Object context;

        public AssetsPathHandler(Object context) {
            this.context = context;
        }
    }

    public static class Builder {
        private String domain = "appassets.androidplatform.com";
        private final java.util.Map<String, PathHandler> handlers = new java.util.HashMap<>();

        public Builder setDomain(String domain) {
            this.domain = domain;
            return this;
        }

        public Builder addPathHandler(String path, PathHandler handler) {
            handlers.put(path, handler);
            return this;
        }

        public WebViewAssetLoader build() {
            return new WebViewAssetLoader(domain, handlers);
        }
    }
}

