public class InstallApkWithFileProvider extends Activity {
    public void installApkFromAsset(String assetName) throws IOException {
        String tempFilename = "temporary.apk";
        byte[] buffer = new byte[16384];

        /* Copy application asset into temporary file */
        try (InputStream is = getAssets().open(assetName);
             FileOutputStream fout = openFileOutput(tempFilename, Context.MODE_PRIVATE)) {
            int n;
            while ((n = is.read(buffer)) >= 0) {
                fout.write(buffer, 0, n);
            }
        }

        /* Expose temporary file with FileProvider */
        File toInstall = new File(this.getFilesDir(), tempFilename);
        // GOOD: The file is protected by FileProvider
        Uri applicationUri = FileProvider.getUriForFile(this, "com.example.apkprovider", toInstall);

        /* Create Intent and set data to APK file. */
        Intent intent = new Intent(Intent.ACTION_INSTALL_PACKAGE);
        intent.setData(applicationUri);
        intent.setFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);

        startActivity(intent);
    }

    public static void main(String[] args) {
        InstallApkWithFileProvider installer = new InstallApkWithFileProvider();
        try {
            String assetName = "dummy_asset.apk";
            // create a small dummy file to simulate an asset
            java.nio.file.Files.write(java.nio.file.Paths.get(assetName), new byte[]{0});
            installer.installApkFromAsset(assetName);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

