public class InstallApkWithPackageInstaller extends Activity {
    private static final String PACKAGE_INSTALLED_ACTION =
        "com.example.SESSION_API_PACKAGE_INSTALLED";

    @Override
    public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        // onCreate left empty; call installApk(...) as needed
    }

    public void installApk(String assetName) throws IOException {
        /* Create the package installer and session */
        PackageInstaller packageInstaller = getPackageManager().getPackageInstaller();
        PackageInstaller.SessionParams params =
            new PackageInstaller.SessionParams(PackageInstaller.SessionParams.MODE_FULL_INSTALL);
        int sessionId = packageInstaller.createSession(params);
        PackageInstaller.Session session = packageInstaller.openSession(sessionId);

        /* Load asset into session */
        try (OutputStream packageInSession = session.openWrite("package", 0, -1);
             InputStream is = getAssets().open(assetName)) {
            byte[] buffer = new byte[16384];
            int n;
            while ((n = is.read(buffer)) >= 0) {
                packageInSession.write(buffer, 0, n);
            }
        }

        /* Create status receiver */
        Intent intent = new Intent(this, InstallApkSessionApi.class);
        intent.setAction(PACKAGE_INSTALLED_ACTION);
        Context context = this;
        PendingIntent pendingIntent = PendingIntent.getActivity(context, 0, intent, 0);
        IntentSender statusReceiver = pendingIntent.getIntentSender();

        /* Commit the session */
        session.commit(statusReceiver);
    }

    public static void main(String[] args) {
        InstallApkWithPackageInstaller installer = new InstallApkWithPackageInstaller();
        try {
            installer.onCreate(new Bundle());
            installer.installApk("sample.apk");
            System.out.println("installApk completed");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

