public class PotentiallyDangerousFunction implements Runnable {
    private volatile Thread blinker;

    private int interval;

    public PotentiallyDangerousFunction(int interval) {
        this.interval = interval;
    }

    public void stop() {
        blinker = null;
    }

    public void run() {
        Thread thisThread = Thread.currentThread();
        while (blinker == thisThread) {
            try {
                Thread.sleep(interval);
            } catch (InterruptedException e){
            }
            repaint();
        }
    }

    // Minimal placeholder so the class compiles and can be used.
    private void repaint() {
        // no-op placeholder
    }

    // Optional convenience to start the runner
    public void start() {
        blinker = new Thread(this);
        blinker.start();
    }

    public static void main(String[] args) {
        PotentiallyDangerousFunction runner = new PotentiallyDangerousFunction(200);
        runner.start();
        try {
            Thread.sleep(1000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        runner.stop();
    }
}

